package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A grade (A, B or C) a person was given, in force from its from-date (null: from the beginning of
 *  time, as the first grade a person was given is). */
@Entity
@Table(name = "person_grade")
public class PersonGrade {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "from_date")
    private LocalDate from;

    protected PersonGrade() {
    }

    public PersonGrade(String sheetId, Long personId, String grade, LocalDate from) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.grade = grade;
        this.from = from;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    public LocalDate getFrom() {
        return from;
    }

    /** Whether the grade is in force on a date: its from-date is none or on or before the date. */
    public boolean appliesOn(LocalDate date) {
        return from == null || !from.isAfter(date);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonGradeRepository extends JpaRepository<PersonGrade, Long> {

    /** The sheet's people's grades. */
    List<PersonGrade> findBySheetId(String sheetId);

    /** A person's grades. */
    List<PersonGrade> findByPersonId(Long personId);

    Optional<PersonGrade> findByPersonIdAndFrom(Long personId, LocalDate from);

    Optional<PersonGrade> findByPersonIdAndFromIsNull(Long personId);
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import org.springframework.stereotype.Service;

/** The grades given to the people on a sheet, each in force from its from-date. */
@Service
public class PersonGradeService {

    /** Grades from the earliest: no from-date first, then by from-date. */
    private static final Comparator<PersonGrade> FROM_EARLIEST =
            Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));

    private final PersonGradeRepository grades;

    public PersonGradeService(PersonGradeRepository grades) {
        this.grades = grades;
    }

    /** A person's grades, from the earliest. */
    public List<PersonGrade> of(Long personId) {
        return grades.findByPersonId(personId).stream().sorted(FROM_EARLIEST).toList();
    }

    /** Each person's grades on the sheet, from the earliest, by person id. */
    public Map<Long, List<PersonGrade>> bySheet(String sheetId) {
        return grades.findBySheetId(sheetId).stream().sorted(FROM_EARLIEST)
                .collect(Collectors.groupingBy(PersonGrade::getPersonId));
    }

    /** The person's grade in force on a date: the one whose from-date is the latest on or before it
     *  (the first grade applies from the beginning of time). */
    public String gradeOn(Long personId, LocalDate date) {
        return gradeOn(of(personId), date);
    }

    /** The grade in force on a date among a person's grades; null when they have none. */
    public static String gradeOn(List<PersonGrade> theirs, LocalDate date) {
        return theirs.stream()
                .filter(g -> g.appliesOn(date))
                .max(FROM_EARLIEST)
                .map(PersonGrade::getGrade)
                .orElse(null);
    }

    /** Give a person a grade from a date (null: from the beginning of time), replacing the one they
     *  had from that date and keeping the others. */
    public PersonGrade give(Person person, String grade, LocalDate from) {
        Optional<PersonGrade> had = from == null
                ? grades.findByPersonIdAndFromIsNull(person.getId())
                : grades.findByPersonIdAndFrom(person.getId(), from);
        PersonGrade given = had
                .map(existing -> {
                    existing.setGrade(grade);
                    return existing;
                })
                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), grade, from));
        return grades.saveAndFlush(given);
    }
}
-- A person's grade is dated: each grade a person is given applies from its from-date, and the one in
-- force on a date is the one whose from-date is the latest on or before it. The first grade a person
-- was given has no from-date and applies from the beginning of time. A person has at most one grade
-- per from-date (no from-date counting as one).
CREATE TABLE person_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade CHAR(1) NOT NULL,
    from_date DATE,
    from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_person_from ON person_grade (person_id, from_key);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;

